#include <charconv>
#include <optional>
#include <string_view>

std::optional<int> parseInt(std::string_view text)
{
    int value{};
    const char* const last{ text.data() + text.size() };
    const auto [end, error]{ std::from_chars(text.data(), last, value) };
    if (error != std::errc{} || end != last || text.empty())
    {
        return std::nullopt;
    }
    return value;
}

unitTests:
TEST("valid numbers") { CHECK(parseInt("42") == 42); CHECK(parseInt("-7") == -7); CHECK(parseInt("0") == 0); }
TEST("not numbers") { CHECK(!parseInt("abc")); CHECK(!parseInt("")); CHECK(!parseInt("-")); }
TEST("the whole text must be a number") { CHECK(!parseInt("12abc")); CHECK(!parseInt("1 2")); CHECK(!parseInt(" 5")); }
TEST("too big for an int") { CHECK(!parseInt("99999999999999999999")); }

